import React from'react';

class NAME_1 extends React.Component {
  state = {
    count: 0
  };

  render() {
    return (
      <div>
        <div>NAME_1</div>
        <div>
          <p>Current count: {this.state.count}</p>
          <Button
            onClick={() => this.setState({ count: this.state.count + 1 })}
          >
            Increment
          </Button>
        </div>
      </div>
    );
  }
}

export default NAME_1;
```
